CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('viewer','engineer','admin')));
CREATE TABLE IF NOT EXISTS assets (id text PRIMARY KEY, name text NOT NULL);
INSERT INTO assets VALUES ('boiler-1','Boiler 1 อสร.หนองจอก') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS uploads (id uuid PRIMARY KEY, asset_id text NOT NULL REFERENCES assets(id), filename text NOT NULL, status text NOT NULL CHECK(status IN ('queued','processing','completed','completed_with_errors','failed')), row_count int NOT NULL DEFAULT 0, rejected_count int NOT NULL DEFAULT 0, alert_count int NOT NULL DEFAULT 0, errors jsonb NOT NULL DEFAULT '[]', created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS observations (upload_id uuid REFERENCES uploads(id), asset_id text REFERENCES assets(id), observed_date date NOT NULL, timezone text NOT NULL CHECK(timezone='Asia/Bangkok'), source_sheet text NOT NULL, source_row int NOT NULL, metrics jsonb NOT NULL, PRIMARY KEY(upload_id,source_sheet,source_row));
CREATE TABLE IF NOT EXISTS alerts (id uuid PRIMARY KEY, event_key text UNIQUE NOT NULL, upload_id uuid REFERENCES uploads(id), asset_id text REFERENCES assets(id), observed_date date NOT NULL, category text NOT NULL, severity text NOT NULL CHECK(severity IN ('info','warning','high')), status text NOT NULL CHECK(status IN ('new','investigating','resolved','false_positive')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feedback (id bigserial PRIMARY KEY, alert_id uuid NOT NULL REFERENCES alerts(id), result text NOT NULL CHECK(result IN ('confirmed_fault','instrument_issue','data_issue','normal_operation','unknown')), cause text NOT NULL, correction text NOT NULL, tags text NOT NULL, outcome text NOT NULL, reviewed_at timestamptz NOT NULL, reviewer_id uuid NOT NULL REFERENCES users(id), attachments jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX IF NOT EXISTS feedback_cursor ON feedback(updated_at,id);
CREATE INDEX IF NOT EXISTS alerts_date ON alerts(observed_date);
